    class UOLSoundConnectorComponent* SoundConnectorComp;
    class UOLWaitPointComponent* WaitPointComponent;
    FLOAT InitialOpenAngle;
    FLOAT MaxOpenAngle;
    FLOAT PlayerOpenedAngle;
    BITFIELD bReverseDirection:1;
    BITFIELD bLocked:1;
    BITFIELD bFakeUnlocked:1;
    BITFIELD bNoLockedInteraction:1;
    BITFIELD bAutoClose:1;
    BITFIELD bCantClose:1;
    BITFIELD bNoPushKnob:1;
