    {
        OLHUD_eventShowSubtitle_Parms Parms(EC_EventParm);
        Parms.MessageText=MessageText;
        ProcessEvent(FindFunctionChecked(OLGAME_ShowSubtitle),&Parms);
    }
    void eventHideObjective()
    {
        ProcessEvent(FindFunctionChecked(OLGAME_HideObjective),NULL);
    }
